/**
 * The Beyond The Sky animated wordmark (brand kit), ported from the website's React component
 * (beyondthesky_new: horizons-export/apps/web/src/components/BrandWordmark.jsx) to plain DOM.
 *
 * BEYOND THE SKY in outlined Zilla Slab letters with the eclipse ring as the "O", THE in small slab
 * caps, INTO THE UNIVERSE underneath. A helium-4 atom (2 protons, 2 neutrons, 2 electrons) traces a
 * Bernoulli lemniscate (∞) through the eclipse (helium was discovered in the Sun's spectrum
 * during the 1868 eclipse). Its trail passes in front of the letters only where it crosses the
 * eclipse. The artwork strings below are the brand kit's own, unchanged.
 */
const NS = 'http://www.w3.org/2000/svg';
const TAU = Math.PI * 2;
const A = 1300; // half-width of the ∞ (SVG units)
const KY = 1.15; // vertical stretch
const CX = 2569; // centre of the ∞ = centre of the eclipse
const CY = 745;
const LAP = 5.5; // seconds per lap
const TRAIL = 0.93; // trail length as a fraction of a lap
const FRONT_R = 360; // the trail is in front only within this distance of the eclipse
const TRAIL_RGB = 'rgb(254,52,31)';

// Arc-length table, for constant-speed motion along the ∞.
const TABLE = (() => {
  const us: number[] = [];
  const ls = [0];
  let px = A, py = 0;
  for (let j = 0; j <= 720; j++) {
    const u = (j / 720) * TAU, s = Math.sin(u), c = Math.cos(u), d = 1 + s * s;
    const x = (A * c) / d, y = (A * KY * s * c) / d;
    us.push(u);
    if (j) ls.push(ls[j - 1] + Math.hypot(x - px, y - py));
    px = x;
    py = y;
  }
  return { us, ls, total: ls[720] };
})();

function uAt(f: number): number {
  const { us, ls, total } = TABLE;
  f = ((f % 1) + 1) % 1;
  const t = f * total;
  let lo = 0, hi = 720;
  while (hi - lo > 1) {
    const m = (lo + hi) >> 1;
    if (ls[m] <= t) lo = m;
    else hi = m;
  }
  return us[lo] + ((t - ls[lo]) / (ls[hi] - ls[lo] || 1)) * (us[hi] - us[lo]);
}

/** A point on the ∞ at fraction f of a lap, and whether the trail there runs in front of the letters. */
export function pointAt(f: number): { x: number; y: number; front: boolean } {
  const u = uAt(f), s = Math.sin(u), c = Math.cos(u), d = 1 + s * s, X = (A * c) / d;
  return { x: CX + X, y: CY + (A * KY * s * c) / d, front: ((u % TAU) + TAU) % TAU < Math.PI && Math.abs(X) < FRONT_R };
}

const DEFS = "<linearGradient id=\"bts-eg\" x1=\"0\" y1=\"1\" x2=\"1\" y2=\"0\"><stop offset=\"0\" stop-color=\"#C1121F\"/><stop offset=\".45\" stop-color=\"#FF2A1A\"/><stop offset=\"1\" stop-color=\"#FF6A2A\"/></linearGradient>\n<radialGradient id=\"bts-cloud\"><stop offset=\"0\" stop-color=\"rgb(254,52,31)\" stop-opacity=\".35\"/><stop offset=\"1\" stop-color=\"rgb(254,52,31)\" stop-opacity=\"0\"/></radialGradient>\n<radialGradient id=\"bts-eglow\"><stop offset=\"0\" stop-color=\"rgb(254,52,31)\" stop-opacity=\".9\"/><stop offset=\"1\" stop-color=\"rgb(254,52,31)\" stop-opacity=\"0\"/></radialGradient>\n<radialGradient id=\"bts-nglow\"><stop offset=\"0\" stop-color=\"#fff\" stop-opacity=\".55\"/><stop offset=\"1\" stop-color=\"#fff\" stop-opacity=\"0\"/></radialGradient>\n";

