/**
 * Put the animated wordmark into `container`. `segments` sets the trail's smoothness (the site
 * uses 90; small sizes need fewer). Returns a function that stops and removes it.
 */
export function mountWordmark(container: HTMLElement, segments = 90): () => void {
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '-200 -200 8326 2050');
  svg.setAttribute('role', 'img');
  svg.setAttribute('aria-label', 'Beyond the Sky: Into the Universe');
  const defs = document.createElementNS(NS, 'defs');
  defs.innerHTML = DEFS;
  const back = document.createElementNS(NS, 'g');
  const art = document.createElementNS(NS, 'g');
  art.innerHTML = ARTWORK;
  const front = document.createElementNS(NS, 'g');
  back.setAttribute('aria-hidden', 'true');
  front.setAttribute('aria-hidden', 'true');
  svg.append(defs, back, art, front);
  container.appendChild(svg);

  const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
  const speed = reduce ? 0.4 : 1;

  // Trail segments: [glow, core].
  const segs: [SVGLineElement, SVGLineElement][] = [];
  for (let i = 0; i < segments; i++) {
    const glow = document.createElementNS(NS, 'line');
    const core = document.createElementNS(NS, 'line');
    for (const el of [glow, core]) {
      el.setAttribute('stroke', TRAIL_RGB);
      el.setAttribute('stroke-linecap', 'butt');
    }
    segs.push([glow, core]);
  }

  // The helium-4 atom.
  const ae = 930, rx = ae * 0.15, ry = ae * 0.06, nr = ae * 0.022, off = nr * 0.95;
  const atom = document.createElementNS(NS, 'g');
  const nucleons: [number, number, string][] = [
    [-off, -off, '#F5F7FA'],
    [off, off, '#F5F7FA'],
    [off, -off, '#9AA3AD'],
    [-off, off, '#9AA3AD'],
  ];
  atom.innerHTML =
    `<circle r="${ae * 0.3}" fill="url(#bts-cloud)"/>` +
    `<ellipse rx="${rx}" ry="${ry}" fill="none" stroke="#fff" stroke-opacity=".28" stroke-width="6"/>` +
    `<circle r="${ae * 0.11}" fill="url(#bts-nglow)"/>` +
    nucleons.map(([x, y, c]) => `<circle cx="${x}" cy="${y}" r="${nr}" fill="${c}"/>`).join('') +
    `<g class="e"><circle r="${ae * 0.07}" fill="url(#bts-eglow)"/><circle r="${ae * 0.02}" fill="#fff"/></g>` +
    `<g class="e"><circle r="${ae * 0.07}" fill="url(#bts-eglow)"/><circle r="${ae * 0.02}" fill="#fff"/></g>`;
  const electrons = atom.querySelectorAll<SVGGElement>('.e');

  let raf = 0;
  let running = false;
  let visible = true;
  const t0 = performance.now();

  const draw = (now: number) => {
    const sec = (now - t0) / 1000;
    const head = (sec * speed) / LAP;
    let prev = pointAt(head - TRAIL);
    for (let i = 0; i < segments; i++) {
      const k = (i + 1) / segments;
      const p = pointAt(head - TRAIL * (1 - k));
      const a = 0.92 * (1 - Math.pow(1 - k, 1.7));
      const group = p.front ? front : back;
      const [glow, core] = segs[i];
      const parts: [SVGLineElement, number, number][] = [
        [glow, 72 * (0.3 + 0.7 * k), a * 0.22],
        [core, 36 * (0.3 + 0.7 * k), a],
      ];
      for (const [el, w, op] of parts) {
        el.setAttribute('x1', String(prev.x));
        el.setAttribute('y1', String(prev.y));
        el.setAttribute('x2', String(p.x));
        el.setAttribute('y2', String(p.y));
        el.setAttribute('stroke-width', String(w));
        el.setAttribute('stroke-opacity', String(op));
        if (el.parentNode !== group) group.appendChild(el);
      }
      prev = p;
    }
    const tilt = ((-0.5 + sec * 0.35 * speed) * 180) / Math.PI;
    const ang = sec * 7 * speed;
    atom.setAttribute('transform', `translate(${prev.x} ${prev.y}) rotate(${tilt})`);
    electrons[0].setAttribute('transform', `translate(${rx * Math.cos(ang)} ${ry * Math.sin(ang)})`);
    electrons[1].setAttribute('transform', `translate(${-rx * Math.cos(ang)} ${-ry * Math.sin(ang)})`);
    // Keep the atom on top of its trail.
    (prev.front ? front : back).appendChild(atom);
  };

  const frame = (now: number) => {
    if (!running) return;
    draw(now);
    raf = requestAnimationFrame(frame);
  };
  const start = () => {
    if (!running && visible && !document.hidden) {
      running = true;
      raf = requestAnimationFrame(frame);
    }
  };
  const stop = () => {
    running = false;
    cancelAnimationFrame(raf);
  };

  draw(performance.now()); // the first frame straight away: no empty flash
  start();

  // Pause when off screen (hidden in photo mode, on phones) or when the tab is hidden.
  const io =
    typeof IntersectionObserver === 'undefined'
      ? undefined
      : new IntersectionObserver(([entry]) => {
          visible = entry.isIntersecting;
          if (visible) start();
          else stop();
        });
  io?.observe(svg);
  const onVis = () => (document.hidden ? stop() : start());
  document.addEventListener('visibilitychange', onVis);

  return () => {
    stop();
    io?.disconnect();
    document.removeEventListener('visibilitychange', onVis);
    svg.remove();
  };
}
